ning.x + dining.width / 2, y: dining.y + dining.height / 2 },\n    queue: { x: door.x + door.width / 2, y: door.y + door.height / 2 },\n  };\n\n  return {\n    compact,\n    feedBeside,\n    topBar: { x: margin, y: margin, width: w - margin * 2, height: topBarHeight },\n    brief: { x: margin, y: briefY, width: w - margin * 2, height: briefHeight },\n    kitchen,\n    pass,\n    dining,\n    door,\n    doorStand,\n    waypoints,\n    tickets: { x: bodyX, y: bodyY + floorHeight + gap, width: bodyWidth, height: ticketsHeight },\n    feed: { x: margin, y: bodyBottom + gap, width: w - margin * 2, height: feedHeight },\n  };\n}\n\nconst COLORS = {\n  ink: 0x241b14,\n  panel: 0x2f241a,\n  cream: 0xfff3d6,\n  kitchen: 0xc9dbd2,\n  kitchenDark: 0x4f796f,\n  dining: 0xecc9a8,\n  wood: 0xb9814f,\n  pass: 0xf2cc5c,\n  door: 0xa8c6da,\n  empty: 0xc7ab86,\n  occupied: 0xe8825f,\n  working: 0x3d9b6d,\n  failed: 0xc73535,\n  ticket: 0xfff8e7,\n  loadOk: 0x3d9b6d,\n  loadWarn: 0xe08b2c,\n  loadHot: 0xc73535,\n  alert: 0xc73535,\n  muted: 0x8d8378,\n} as const;\n\nconst ROLE_COLORS: Record<Role, number> = {\n  host: 0x9763bd,\n  supply_lead: 0xe69b2e,\n  chef: 0xe44f3f,\n  server: 0x3d73bf,\n  expediter: 0xe69b2e,\n};\n\nconst STATUS_COLORS: Record<OrderStatus, number> = {\n  queued: 0x8d8378,\n  seated: 0x6f8fb5,\n  preparing: 0xe08b2c,\n  ready: 0x3d9b6d,\n  served: 0x4f796f,\n  cancelled: 0xc73535,\n};\n\nconst VOICE_COLORS: Record<string, string> = {\n  host: \"#c79bea\",\n  supply_lead: \"#f4bf6a\",\n  chef: \"#ff8f80\",\n  server: \"#8ab6ef\",\n  expediter: \"#f4bf6a\",\n  house: \"#c9bdae\",\n  you: \"#7ddc9f\",\n};\n\nconst MONO = 'ui-monospace, \"SF Mono\", Menlo, monospace';\n/** Spoken lines — a person talking, not a log. */\nconst DISPLAY = '\"Iowan Old Style\", Palatino, \"Palatino Linotype\", Georgia, serif';\n/** Buttons, names, UI copy. */\nconst SANS = '\"Avenir Next\", \"Segoe UI\", \"Helvetica Neue\", system-ui, sans-serif';\n\nconst DEFAULT_STAFF: Record<Role, { 