export interface RestaurantArenaSceneHandle {
  render(state: RestaurantArenaState): void;
  setWorkerStatus(role: Role, status: RestaurantArenaWorkerStatus): void;
  destroy(): void;
}

export function mountRestaurantArenaScene(
  parent: HTMLElement,
