/**
 * Where every part of the Restaurant Arena floor goes, for a given canvas.
 *
 * The scene used to hardcode a single 520×740-ish arrangement and clamp text
 * to one size, which made the floor read as a postage stamp inside a maximised
 * window and cut the ticket rail off inside a short one. This module is the
 * one place that answers "how big is everything", so the scene can stay a
 * painter: it hands back plain rectangles in CSS-pixel units plus the two
 * numbers the painter needs to size things itself (`scale`, `compact`).
 *
 * Three rules drive the whole file:
 *
 *   1. Every rect returned fits inside `width` × `height`. Callers draw
 *      straight from these numbers, so a rect that pokes out of the canvas is
 *      a clipped panel, not a rounding detail. Heights and widths are
 *      allocated by subtraction from the space actually available (never by
 *      summing independent constants), so the arithmetic can't drift.
 *   2. Growth is proportional, not one-dimensional: `scale` follows the
 *      *smaller* of the two axes' growth, so a very wide, short window doesn't
 *      scale text up past the point where the floor still fits vertically.
 *   3. Small windows stop growing rather than start shrinking. Under
 *      `COMPACT_WIDTH`/`COMPACT_HEIGHT` the layout switches to its tight
 *      variant and pins `scale` at 1 — shrinking type below the baseline
 *      buys a few pixels and costs legibility.
 */

export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  compact: boolean;
  scale: number;
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

/** The window this game was drawn for: `scale` is exactly 1 here. */
export const ARENA_BASE_WIDTH = 520;
export const ARENA_BASE_HEIGHT = 740;

/**
 * Past roughly double the baseline the floor is already comfortable and more
 * growth just wastes the extra room on padding, so text and furniture stop
 * here and the zones take the remaining space instead.
 */
export const ARENA_MAX_SCALE = 1.9;

/** Under either of these the tight layout wins and `scale` pins at 1. */
export const ARENA_COMPACT_WIDTH = 460;
export const ARENA_COMPACT_HEIGHT = 420;

/**
 * Wide enough that the service log can sit *beside* the floor without
 * squeezing the dining room — below it the log stacks underneath instead.
 */
export const ARENA_FEED_BESIDE_WIDTH = 600;

/**
 * The host stand is a drop target and a label, so it stops shrinking well
 * before the rest of the door does — see `doorStand` below.
 */
export const ARENA_MIN_STAND_WIDTH = 56;
export const ARENA_MIN_STAND_HEIGHT = 22;

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/**
 * `scale` for a canvas: 1 at the baseline and below it, growing with whichever
 * axis has the least room to spare, capped at `ARENA_MAX_SCALE`.
 */
function arenaScale(w: number, h: number, compact: boolean): number {
  if (compact) return 1;
  const growth = Math.min(w / ARENA_BASE_WIDTH, h / ARENA_BASE_HEIGHT);
  return clamp(growth, 1, ARENA_MAX_SCALE);
}

export function restaurantArenaLayout(width: number, height: number): RestaurantArenaLayout {
  // Below this the arena isn't a playable floor at any layout, and the
  // subtraction below would start handing back negative rows; a canvas this
  // small only shows up mid-teardown or mid-first-layout-pass.
  const w = Math.max(200, Math.round(Number.isFinite(width) ? width : 0));
  const h = Math.max(200, Math.round(Number.isFinite(height) ? height : 0));

  const compact = w < ARENA_COMPACT_WIDTH || h < ARENA_COMPACT_HEIGHT;
  const scale = arenaScale(w, h, compact);
  const feedBeside = w >= ARENA_FEED_BESIDE_WIDTH;
  /** A baseline-authored size in this canvas' units. */
  const px = (base: number) => Math.round(base * scale);

  const margin = compact ? 6 : px(8);
  const gap = compact ? 4 : px(6);

  // Chrome rows are capped by a share of the canvas as well as by their
  // design size, so a short window loses a few pixels of top bar rather than
  // its entire ticket rail.
  const topBarHeight = Math.min(compact ? 30 : px(38), Math.round(h * 0.13));
  const briefHeight = Math.min(compact ? 26 : px(32), Math.round(h * 0.11));

  const contentX = margin;
  const contentWidth = w - margin * 2;
  const briefY = margin + topBarHeight + gap;
  const bodyY = briefY + briefHeight + gap;
  /** Everything left under the brief: floor + tickets, plus the feed if it stacks. */
  const availHeight = h - margin - bodyY;

  // ── Columns: floor block, and the feed beside it if there's room ──────
  let bodyWidth = contentWidth;
  let feedWidth = contentWidth;
  if (feedBeside) {
    const wanted = clamp(Math.round(contentWidth * 0.3), 170, 360);
    // The floor is the game; the log gives back width before the floor does.
    feedWidth = Math.min(wanted, Math.round(contentWidth * 0.42));
    bodyWidth = contentWidth - feedWidth - gap;
  }

  // ── Rows: the feed's stacked strip, then floor over tickets ───────────
  const minFloorHeight = Math.min(compact ? 78 : px(110), Math.round(availHeight * 0.45));
  const minTicketsHeight = Math.min(compact ? 28 : px(56), Math.round(availHeight * 0.12));
  const minBodyHeight = minFloorHeight + gap + minTicketsHeight;

  let bodyHeight = availHeight;
  let feedHeight = availHeight;
  if (!feedBeside) {
    const wanted = Math.max(
      Math.min(compact ? 46 : px(96), Math.round(availHeight * 0.18)),
      Math.round(availHeight * 0.2),
    );
    feedHeight = Math.min(wanted, availHeight - gap - minBodyHeight);
    bodyHeight = availHeight - gap - feedHeight;
  }

  let ticketsHeight = Math.min(
    compact ? 56 : px(72),
    Math.max(minTicketsHeight, Math.round(bodyHeight * 0.16)),
  );
  let floorHeight = bodyHeight - gap - ticketsHeight;
  if (floorHeight < minFloorHeight) {
    // Tickets are a rail of cards and read fine short; the floor is the game.
    floorHeight = minFloorHeight;
    ticketsHeight = bodyHeight - gap - floorHeight;
  }

  // ── Inside the floor: kitchen | pass | (dining over door) ─────────────
  // Shares of one measured strip rather than three independent widths, so
  // the three zones plus their gaps always add back up to `bodyWidth`.
  const strip = bodyWidth - gap * 2;
  const passWidth = Math.max(6, Math.min(Math.round(strip * 0.075), px(60)));
  const kitchenWidth = Math.max(
    6,
    Math.min(Math.round(strip * 0.28), strip - passWidth - Math.round(strip * 0.34)),
  );
  const diningWidth = strip - passWidth - kitchenWidth;

  const labelHeight = compact ? 12 : px(14);
  const minDoorHeight = Math.min(labelHeight + ARENA_MIN_STAND_HEIGHT + 4, Math.round(floorHeight * 0.42));
  const minDiningHeight = Math.min(compact ? 32 : px(60), Math.round(floorHeight * 0.3));
  let doorHeight = Math.max(minDoorHeight, Math.round(floorHeight * 0.32));
  let diningHeight = floorHeight - gap - doorHeight;
  if (diningHeight < minDiningHeight) {
    diningHeight = minDiningHeight;
    doorHeight = Math.max(1, floorHeight - gap - diningHeight);
    diningHeight = floorHeight - gap - doorHeight;
  }

  const kitchen: ArenaRect = { x: contentX, y: bodyY, width: kitchenWidth, height: floorHeight };
  const pass: ArenaRect = {
    x: kitchen.x + kitchen.width + gap,
    y: bodyY,
    width: passWidth,
    height: floorHeight,
  };
  const diningX = pass.x + pass.width + gap;
  const dining: ArenaRect = { x: diningX, y: bodyY, width: diningWidth, height: diningHeight };
  const door: ArenaRect = {
    x: diningX,
    y: dining.y + dining.height + gap,
    width: diningWidth,
    height: doorHeight,
  };

  // The stand is what a party walks up to and what a dragged host is dropped
  // on, so it keeps a hittable size (>= 56×22) even when the door around it
  // has been squeezed — a 12px sliver is neither a target nor a landmark.
  const standWidth = Math.max(
    ARENA_MIN_STAND_WIDTH,
    Math.min(px(90), Math.round(door.width * 0.36)),
  );
  const standHeight = Math.max(
    ARENA_MIN_STAND_HEIGHT,
    Math.min(px(36), door.height - labelHeight - 4),
  );
  // Left gutter so waiting parties have somewhere to queue up beside it.
  const gutter = clamp(px(40), 4, Math.max(4, door.width - standWidth - 6));
  const doorStand: ArenaRect = {
    x: clamp(door.x + gutter, contentX, Math.max(contentX, w - margin - standWidth)),
    y: clamp(door.y + labelHeight, door.y, Math.max(door.y, h - margin - standHeight)),
    width: standWidth,
    height: standHeight,
  };

  /**
   * The hallway: one horizontal line staff walk along instead of cutting
   * diagonally through the tables. It sits at the dining room's midline,
   * which — since the pass spans the full floor height and the dining room
   * starts at its top — is always inside the pass zone too, so the four
   * stations really are strung along one corridor.
   */
  const spineY = dining.y + dining.height / 2;

  const waypoints: Record<ArenaLocation, ArenaPoint> = {
    kitchen: { x: kitchen.x + kitchen.width / 2, y: kitchen.y + kitchen.height / 2 },
    pass: { x: pass.x + pass.width / 2, y: spineY },
    floor: { x: dining.x + dining.width / 2, y: spineY },
    queue: { x: doorStand.x + doorStand.width / 2, y: doorStand.y + doorStand.height / 2 },
  };

  return {
    compact,
    scale,
    feedBeside,
    topBar: { x: contentX, y: margin, width: contentWidth, height: topBarHeight },
    brief: { x: contentX, y: briefY, width: contentWidth, height: briefHeight },
    kitchen,
    pass,
    dining,
    door,
    doorStand,
    waypoints,
    spineY,
    tickets: {
      x: contentX,
      y: bodyY + floorHeight + gap,
      width: bodyWidth,
      height: ticketsHeight,
    },
    feed: feedBeside
      ? { x: contentX + bodyWidth + gap, y: bodyY, width: feedWidth, height: bodyHeight }
      : { x: contentX, y: bodyY + bodyHeight + gap, width: contentWidth, height: feedHeight },
  };
}

