/**
 * Staff movement across the Restaurant Arena floor.
 *
 * The floor is four stations strung along one hallway:
 *
 *     kitchen ── pass ── floor ── queue
 *
 * The pass and the dining floor are through-stations, not endpoints: nobody
 * teleports from the kitchen to the front door, they carry the plate out
 * through the pass, cross the dining room and end up at the host stand. That
 * is the whole reason this is a graph and not a lookup — `bfsPath` reports the
 * stations a trip passes through, and `corridorPoints` turns those stations
 * into pixels that ride the hallway (`spineY`, from the layout module) instead
 * of cutting a diagonal line through the tables.
 *
 * `StaffWalker` is the per-worker state that survives a repaint: the scene
 * destroys and rebuilds every game object when it paints, so the walker — not
 * the sprite — owns where a person actually is, which way they're facing, and
 * how far into the current hop they've got.
 */

import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

/**
 * The hallway, as an adjacency list. Every edge is walkable both ways; the
 * kitchen and the queue are the two ends, so any trip between them is forced
 * through the pass *and* the dining floor.
 */
export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

/** A brisk service walk. Fast enough to look busy, slow enough to follow. */
export const WALK_SPEED_PX_PER_SEC = 200;

/** Nodes are all a graph away from each other, so the walk order is a BFS. */
export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const previous = new Map<WalkNode, WalkNode>();
  const seen = new Set<WalkNode>([from]);
  const queue: WalkNode[] = [from];
  while (queue.length > 0) {
    const node = queue.shift()!;
    for (const next of WALK_GRAPH[node]) {
      if (seen.has(next)) continue;
      seen.add(next);
      previous.set(next, node);
      if (next === to) {
        const path: WalkNode[] = [to];
        let cursor: WalkNode = to;
        while (cursor !== from) {
          cursor = previous.get(cursor)!;
          path.unshift(cursor);
        }
        return path;
      }
      queue.push(next);
    }
  }
  return [from];
}

function samePoint(a: Point, b: Point): boolean {
  return Math.abs(a.x - b.x) < 0.001 && Math.abs(a.y - b.y) < 0.001;
}

/**
 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
 * hallway instead of cutting diagonally through a room.
 *
 * Each leg is at most three straight moves — out to the hallway, along it,
 * then in to the station — so every segment of the returned path is
 * axis-aligned. Zero-length moves are dropped, so a station already on the
 * hallway costs one segment, not three. The path includes `start` as its
 * first point.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [{ x: start.x, y: start.y }];
  const push = (point: Point) => {
    const last = points[points.length - 1]!;
    if (!samePoint(last, point)) points.push(point);
  };
  for (const node of nodes) {
    const target = waypoints[node];
    if (!target) continue;
    const from = points[points.length - 1]!;
    if (samePoint(from, target)) continue;
    // Step out to the hallway before moving sideways, and only step off it
    // once we're above/below the station we're headed for.
    if (from.x !== target.x) {
      push({ x: from.x, y: spineY });
      push({ x: target.x, y: spineY });
    }
    push({ x: target.x, y: target.y });
  }
  return points;
}

/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
export function hopDurationMs(from: Point, to: Point): number {
  const distance = Math.hypot(to.x - from.x, to.y - from.y);
  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
}

/** Ease in and out of each hop, so a walk starts and lands instead of snapping. */
function ease(t: number): number {
  return t * t * (3 - 2 * t);
}

interface Hop {
  from: Point;
  to: Point;
  ms: number;
  /** Set when this hop lands exactly on a station, so `node` stays honest. */
  node?: WalkNode;
}

export class StaffWalker {
  x: number;
  y: number;
  facing: 1 | -1 = 1;
  walking = false;
  /** True while the player has this worker's token in hand. */
  dragging = false;
  /** The station the walker is at — or has most recently walked through. */
