/**
 * Holds Restaurant Arena repaints back for the length of a drag.
 *
 * The scene repaints by destroying every game object and rebuilding it — that
 * is fine forty times a second while the player is watching, and fatal while
 * they are holding a staff token: the token under the cursor is destroyed
 * mid-gesture, so the figure snaps back to its old station and the drop never
 * lands. Ticks, worker-status pushes and state patches all arrive on their own
 * schedule and don't care that a drag is open, so the drag can't be the thing
 * that has to know about all of them.
 *
 * So this is one small piece of state between the two: paints go through
 * immediately, unless a drag is open, in which case *at most one* is owed and
 * replayed when the drag ends. One, not a queue — a repaint draws the current
 * state from scratch, so ten held paints and one held paint are the same
 * picture. A resize is the exception: it tears the whole canvas down and
 * rebuilds it at the new size, which both cancels any drag in flight (the
 * token being dragged no longer exists) and satisfies anything owed, so it
 * clears both — a `dragend` that straggles in afterwards has nothing left to
 * replay.
 */
export class RepaintGate {
  private dragging = false;
  private owed = false;

  /** True while a drag is open (between beginDrag() and endDrag()/resize()). */
  get isDragging(): boolean {
    return this.dragging;
  }

  beginDrag(): void {
    this.dragging = true;
  }

  /**
   * Paints immediately (returns true) unless a drag is open, in which case
   * the paint is held back (returns false) and one repaint becomes owed.
   */
  requestPaint(): boolean {
    if (this.dragging) {
      this.owed = true;
      return false;
    }
    return true;
  }

  /**
   * Ends the drag. Returns whether a repaint was held back during it
   * (and thus needs to be replayed by the caller now).
   */
  endDrag(): boolean {
    const owed = this.owed;
    this.dragging = false;
    this.owed = false;
    return owed;
  }

  /**
   * Drops any open drag and clears anything owed, since the resize itself
   * repaints from scratch.
   */
  resize(): void {
    this.dragging = false;
    this.owed = false;
  }
}

