cat > /tmp/verify-layout.ts <<'EOF'
import { restaurantArenaLayout, type RestaurantArenaLayout, type ArenaRect } from "./overlay/restaurant-arena-layout.js";
import { bfsPath, corridorPoints, hopDurationMs, StaffWalker } from "./overlay/staff-walk.js";

const sizes: [number, number][] = [];
for (const w of [200, 240, 320, 380, 459, 460, 520, 599, 600, 700, 900, 1200, 1600, 2400, 3840]) {
  for (const h of [200, 240, 300, 419, 420, 500, 740, 900, 1200, 1600, 2160]) sizes.push([w, h]);
}
sizes.push([1024, 768], [1440, 900], [375, 667], [800, 600]);

let bad = 0;
const rectKeys = ["topBar","brief","kitchen","pass","dining","door","doorStand","tickets","feed"] as const;
for (const [w, h] of sizes) {
  const L = restaurantArenaLayout(w, h);
  const fail = (m: string) => { bad++; console.log(`${w}x${h}: ${m}`); };
  const W = Math.max(200, w), H = Math.max(200, h);
  for (const k of rectKeys) {
    const r = L[k] as ArenaRect;
    if (r.width <= 0 || r.height <= 0) fail(`${k} non-positive ${JSON.stringify(r)}`);
    if (r.x < 0 || r.y < 0 || r.x + r.width > W + 0.001 || r.y + r.height > H + 0.001) fail(`${k} outside ${JSON.stringify(r)}`);
  }
  if (L.doorStand.width < 56 || L.doorStand.height < 22) fail(`stand too small ${JSON.stringify(L.doorStand)}`);
  if (L.scale < 1 || L.scale > 1.9) fail(`scale ${L.scale}`);
  if (L.compact && L.scale !== 1) fail(`compact scale ${L.scale}`);
  if (L.spineY < L.pass.y || L.spineY > L.pass.y + L.pass.height) fail(`spine outside pass`);
  if (L.spineY < L.dining.y || L.spineY > L.dining.y + L.dining.height) fail(`spine outside dining`);
  // no overlap of the major zones
  const pairs: [string, ArenaRect][] = [["topBar",L.topBar],["brief",L.brief],["kitchen",L.kitchen],["pass",L.pass],["dining",L.dining],["door",L.door],["tickets",L.tickets],["feed",L.feed]];
  for (let i=0;i<pairs.length;i++) for (let j=i+1;j<pairs.length;j++) {
    const [an,a]=pairs[i]!,[bn,b]=pairs[j]!;
    const overlap = a.x < b.x+b.width-0.001 && b.x < a.x+a.width-0.001 && a.y < b.y+b.height-0.001 && b.y < a.y+a.height-0.001;
    if (overlap) fail(`${an} overlaps ${bn}`);
  }
  // waypoints inside their zones
