}
console.log("bfs kitchen->queue", bfsPath("kitchen","queue"));
console.log("bfs queue->kitchen", bfsPath("queue","kitchen"));
console.log("bfs floor->floor", bfsPath("floor","floor"));
console.log("hop 200px", hopDurationMs({x:0,y:0},{x:200,y:0}));
const wk = new StaffWalker("kitchen", base.waypoints.kitchen);
