/**
 * Each role stands in its own lane either side of a station's waypoint, so
 * four people at one station don't pile into one figure. The lane is fixed
 * per role rather than assigned in arrival order: an order-based lane would
 * shuffle everyone sideways the moment one worker walked off somewhere else,
 * which reads as the whole brigade twitching over a change that involved
 * one person.
 */
private lane(role: Role): number {
  const index = LANE_ORDER.indexOf(role === "expediter" ? "supply_lead" : role);
  return (index < 0 ? 0 : index) - (LANE_ORDER.length - 1) / 2;
}

/** `layout.waypoints`, shifted into `role`'s lane — where that role parks. */
private laneWaypoints(role: Role, layout: RestaurantArenaLayout): Record<Location, { x: number; y: number }> {
  const shift = this.lane(role) * this.sp(layout.compact ? 17 : 22);
  const slots = {} as Record<Location, { x: number; y: number }>;
  for (const location of WALK_LOCATIONS) {
    const waypoint = layout.waypoints[location];
    slots[location] = { x: waypoint.x + shift, y: waypoint.y };
  }
  return slots;
}

private walkerFor(role: Role, location: Location, slots: Record<Location, { x: number; y: number }>): StaffWalker {
  const existing = this.walkers.get(role);
  if (existing) return existing;
  // First sight of this worker: park them where they already are rather
  // than walking them in from wherever the map's default happens to be.
  const walker = new StaffWalker(location, slots[location]);
  this.walkers.set(role, walker);
  return walker;
}

private drawWorkers(layout: RestaurantArenaLayout): void {
  const compact = layout.compact;
  this.staffTokens.clear();
  const present = new Set<Role>();

  for (const worker of this.state.workers) {
    const role = worker.role;
    present.add(role);
    const location = this.visualLocation(worker);
    const slots = this.laneWaypoints(role, layout);
    const walker = this.walkerFor(role, location, slots);
    // The state is the destination, not the position: a worker who has just
    // been sent to the pass walks there over the next second or so, and
    // `update()` below is what moves them.
    if (!walker.dragging) walker.setTarget(location, slots, layout.spineY);

    const token = this.buildAvatar(walker.x, walker.y, role, worker.load, compact, !walker.walking);
    this.staffTokens.set(role, token);
    this.faceToken(token, walker.facing);
    const heldHost = role === "host" && Boolean(this.state.seatingHeld) && location === "queue";
    const status = heldHost ? "acting" : (this.workerStatuses.get(role) ?? this.workerStatus(worker));
    this.drawWorkerBadge(token, status, compact, heldHost);
    this.drawSpeechBubble(token, role, compact);
    this.makeDraggable(token, role, layout, slots);
    if (walker.dragging) token.setDepth(80);
  }

  for (const role of [...this.walkers.keys()]) {
    if (!present.has(role)) this.walkers.delete(role);
  }
}

/** Mirror the figure — not its name tag or badge — so a walk has a direction. */
private faceToken(token: Phaser.GameObjects.Container, facing: 1 | -1): void {
  const figure = token.getByName("figure") as Phaser.GameObjects.Container | null;
  figure?.setScale(facing, 1);
}

/**
 * Moves the staff along their walks between paints. A paint is a whole
 * rebuild of the scene and only happens when something changes; a walk is
 * per-frame motion, so it belongs here and drives the existing token
 * instead of asking for a repaint 60 times a second.
 */
update(_time: number, delta: number): void {
  const layout = this.lastLayout;
  if (!layout) return;
  // The staff move on the shift's clock: pausing the shift parks everyone
  // mid-floor, and 2× service means 2× walking.
  const speed = this.running ? Math.max(0, this.state.sim?.speed ?? 1) : 0;
  for (const [role, walker] of this.walkers) {
    if (!walker.step(delta, speed)) continue;
    const token = this.staffTokens.get(role);
    if (!token) continue;
    // The idle bob owns `token.y` when it's running, so it has to let go
    // for the length of the walk and be handed back at the far end.
    this.tweens.killTweensOf(token);
    token.setPosition(walker.x, walker.y);
    this.faceToken(token, walker.facing);
    if (!walker.walking) this.startIdleBob(token, walker.y, role);
  }
}

/**
 * Dragging a worker onto a zone is how the player staffs the floor, so the
 * token itself is the control — pick a person up, drop them on the kitchen,
 * they're on the kitchen.
 *
 * Two things make this survivable. The `RepaintGate` keeps ticks from
 * rebuilding the scene (and so destroying the token) mid-gesture, and the
 * walker is snapped to the drop point before the action is dispatched, so
 * the figure stays where it was let go instead of flicking back to its old
 * station for the frame before the new state arrives.
 */
private makeDraggable(
  token: Phaser.GameObjects.Container,
  role: Role,
  layout: RestaurantArenaLayout,
  slots: Record<Location, { x: number; y: number }>,
): void {
  const walker = this.walkers.get(role);
  if (!walker) return;
  const width = this.sp(layout.compact ? 26 : 34);
  const height = this.sp(layout.compact ? 34 : 44);
  // Containers have no texture to infer a hit area from, so the size has to
  // be set before `setInteractive` — Phaser centres the box on the
  // container's own origin, which is where the figure is drawn.
  token.setSize(width, height);
  token.setInteractive({ draggable: true, useHandCursor: true });

  let moved = false;
  token.on("dragstart", () => {
    moved = false;
    walker.dragging = true;
    this.repaintGate.beginDrag();
    this.tweens.killTweensOf(token);
    token.setDepth(80);
  });
  token.on("drag", (_pointer: Phaser.Input.Pointer, dragX: number, dragY: number) => {
    moved = true;
    token.setPosition(dragX, dragY);
    // Keep the walker under the cursor too: if the held repaint is replayed
    // the token is rebuilt from the walker's position, not the sprite's.
    walker.x = dragX;
    walker.y = dragY;
  });
  token.on("dragend", () => {
    walker.dragging = false;
    const dropped = moved ? this.zoneAt(token.x, token.y, layout) : undefined;
    const owed = this.repaintGate.endDrag();
    const target = dropped ?? walker.node;
    walker.snap(slots[target], target);
    if (dropped && dropped !== this.assignedLocation(role)) {
      // The game owns the roster; this is a request, and the repaint that
      // follows the resulting state is what makes it official.
      this.onAction(`assign_${role}_${dropped}`);
    }
    // Either replay the paint the drag held back, or paint because the token
    // moved — a press with no drag at all needs neither.
    if (owed || moved) this.paint();
  });
}

/** Where the state says this worker is (as opposed to where they're drawn). */
private assignedLocation(role: Role): Location | undefined {
  return this.state.workers.find((worker) => worker.role === role)?.location;
}

/** Which zone a dropped token landed on, if any. */
private zoneAt(x: number, y: number, layout: RestaurantArenaLayout): Location | undefined {
  const inside = (rect: ArenaRect) =>
    x >= rect.x && x <= rect.x + rect.width && y >= rect.y && y <= rect.y + rect.height;
  if (inside(layout.kitchen)) return "kitchen";
  if (inside(layout.pass)) return "pass";
  if (inside(layout.dining)) return "floor";
  if (inside(layout.door) || inside(layout.doorStand)) return "queue";
  return undefined;
}

