        fontStyle: "bold",
      })
      .setDepth(63);
    this.add
      .text(rect.x + 10, rect.y + (compact ? 24 : 28), option.detail, {
        color: "#e2d4c0",
        fontFamily: SANS,
        fontSize: compact ? this.fs(9) : this.fs(10),
        wordWrap: { width: rect.width - 20 },
