import { describe, expect, it } from "bun:test";
import {
  ARENA_BASE_HEIGHT,
  ARENA_BASE_WIDTH,
  ARENA_MAX_SCALE,
  restaurantArenaLayout,
  type ArenaRect,
  type RestaurantArenaLayout,
} from "./restaurant-arena-layout.js";

const RECT_KEYS = [
  "topBar",
  "brief",
  "kitchen",
  "pass",
  "dining",
  "door",
  "doorStand",
  "tickets",
  "feed",
] as const;

const rects = (layout: RestaurantArenaLayout): [string, ArenaRect][] =>
  RECT_KEYS.map((key) => [key, layout[key]]);

const SIZES: [number, number][] = [
  [320, 240],
  [375, 667],
  [460, 420],
  [520, 740],
  [599, 900],
  [600, 500],
  [800, 600],
  [1024, 768],
  [1440, 900],
  [1600, 1200],
  [2400, 1000],
  [3840, 2160],
];

describe("restaurantArenaLayout", () => {
  it("scales 1:1 at the 520x740 baseline", () => {
    const layout = restaurantArenaLayout(ARENA_BASE_WIDTH, ARENA_BASE_HEIGHT);
    expect(layout.scale).toBe(1);
    expect(layout.compact).toBe(false);
  });

  it("grows with whichever axis has the least room, and stops at the cap", () => {
    // Twice the baseline height but only 1.2x the width: the width decides.
    const wide = restaurantArenaLayout(Math.round(ARENA_BASE_WIDTH * 1.2), ARENA_BASE_HEIGHT * 2);
    expect(wide.scale).toBeCloseTo(1.2, 2);
    const tall = restaurantArenaLayout(ARENA_BASE_WIDTH * 2, Math.round(ARENA_BASE_HEIGHT * 1.35));
    expect(tall.scale).toBeCloseTo(1.35, 2);
    // Never below 1 either: a sub-baseline window keeps baseline type.
    expect(restaurantArenaLayout(480, 500).scale).toBe(1);
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      expect(layout.scale).toBeGreaterThanOrEqual(1);
      expect(layout.scale).toBeLessThanOrEqual(ARENA_MAX_SCALE);
    }
    expect(restaurantArenaLayout(4000, 6000).scale).toBe(ARENA_MAX_SCALE);
  });

  it("stays compact and skips growing text on a small window", () => {
    for (const [w, h] of [
      [440, 800],
      [900, 380],
      [320, 240],
    ] as [number, number][]) {
      const layout = restaurantArenaLayout(w, h);
      expect(layout.compact).toBe(true);
      expect(layout.scale).toBe(1);
    }
    expect(restaurantArenaLayout(520, 500).compact).toBe(false);
  });

  it("puts the feed beside the floor only once the window is wide enough", () => {
    const stacked = restaurantArenaLayout(520, 740);
    expect(stacked.feedBeside).toBe(false);
    // Stacked: under the floor block, full content width.
    expect(stacked.feed.y).toBeGreaterThan(stacked.tickets.y + stacked.tickets.height);
    expect(stacked.feed.width).toBeGreaterThan(stacked.dining.width);

    const beside = restaurantArenaLayout(900, 740);
    expect(beside.feedBeside).toBe(true);
    // Beside: to the right of the floor block, sharing its top edge.
    expect(beside.feed.x).toBeGreaterThanOrEqual(beside.tickets.x + beside.tickets.width);
    expect(beside.feed.y).toBe(beside.kitchen.y);
  });

  it("keeps every rect inside the canvas", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      for (const [name, rect] of rects(layout)) {
        expect(rect.width, `${name} width at ${w}x${h}`).toBeGreaterThan(0);
        expect(rect.height, `${name} height at ${w}x${h}`).toBeGreaterThan(0);
        expect(rect.x, `${name} x at ${w}x${h}`).toBeGreaterThanOrEqual(0);
        expect(rect.y, `${name} y at ${w}x${h}`).toBeGreaterThanOrEqual(0);
        expect(rect.x + rect.width, `${name} right at ${w}x${h}`).toBeLessThanOrEqual(w);
        expect(rect.y + rect.height, `${name} bottom at ${w}x${h}`).toBeLessThanOrEqual(h);
      }
    }
  });

  it("keeps the host stand hittable at any size", () => {
    for (const [w, h] of SIZES) {
      const { doorStand } = restaurantArenaLayout(w, h);
      expect(doorStand.width, `stand width at ${w}x${h}`).toBeGreaterThanOrEqual(56);
      expect(doorStand.height, `stand height at ${w}x${h}`).toBeGreaterThanOrEqual(22);
    }
  });

  it("runs the hallway line through the pass zone", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      expect(layout.spineY).toBeGreaterThanOrEqual(layout.pass.y);
      expect(layout.spineY).toBeLessThanOrEqual(layout.pass.y + layout.pass.height);
    }
  });

  it("parks staff on their stations, with the queue on the host stand", () => {
    const layout = restaurantArenaLayout(520, 740);
    const inside = (point: { x: number; y: number }, rect: ArenaRect) =>
      point.x >= rect.x &&
      point.x <= rect.x + rect.width &&
      point.y >= rect.y &&
      point.y <= rect.y + rect.height;
    expect(inside(layout.waypoints.kitchen, layout.kitchen)).toBe(true);
    expect(inside(layout.waypoints.pass, layout.pass)).toBe(true);
    expect(inside(layout.waypoints.floor, layout.dining)).toBe(true);
    expect(inside(layout.waypoints.queue, layout.doorStand)).toBe(true);
    expect(layout.waypoints.queue).toEqual({
      x: layout.doorStand.x + layout.doorStand.width / 2,
      y: layout.doorStand.y + layout.doorStand.height / 2,
    });
  });

  it("never overlaps two zones", () => {
    for (const [w, h] of SIZES) {
      const layout = restaurantArenaLayout(w, h);
      const all = rects(layout).filter(([name]) => name !== "doorStand");
      for (let i = 0; i < all.length; i++) {
        for (let j = i + 1; j < all.length; j++) {
          const [aName, a] = all[i]!;
          const [bName, b] = all[j]!;
          const overlaps =
            a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;
          expect(overlaps, `${aName} vs ${bName} at ${w}x${h}`).toBe(false);
        }
      }
    }
  });
});

