1	/**
2	 * Staff movement across the Restaurant Arena floor.
3	 *
4	 * The floor is four stations strung along one hallway:
5	 *
6	 *     kitchen ── pass ── floor ── queue
7	 *
8	 * The pass and the dining floor are through-stations, not endpoints: nobody
9	 * teleports from the kitchen to the front door, they carry the plate out
10	 * through the pass, cross the dining room and end up at the host stand. That
11	 * is the whole reason this is a graph and not a lookup — `bfsPath` reports the
12	 * stations a trip passes through, and `corridorPoints` turns those stations
13	 * into pixels that ride the hallway (`spineY`, from the layout module) instead
14	 * of cutting a diagonal line through the tables.
15	 *
16	 * `StaffWalker` is the per-worker state that survives a repaint: the scene
17	 * destroys and rebuilds every game object when it paints, so the walker — not
18	 * the sprite — owns where a person actually is, which way they're facing, and
19	 * how far into the current hop they've got.
20	 */
21	
22	import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";
23	
24	export type WalkNode = ArenaLocation;
25	export type Point = ArenaPoint;
26	
27	/**
28	 * The hallway, as an adjacency list. Every edge is walkable both ways; the
29	 * kitchen and the queue are the two ends, so any trip between them is forced
30	 * through the pass *and* the dining floor.
31	 */
32	export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
33	  kitchen: ["pass"],
34	  pass: ["kitchen", "floor"],
35	  floor: ["pass", "queue"],
36	  queue: ["floor"],
37	};
38	
39	/** A brisk service walk. Fast enough to look busy, slow enough to follow. */
40	export const WALK_SPEED_PX_PER_SEC = 200;
41	
42	/** Nodes are all a graph away from each other, so the walk order is a BFS. */
43	export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
44	  if (from === to) return [from];
45	  const previous = new Map<WalkNode, WalkNode>();
46	  const seen = new Set<WalkNode>([from]);
47	  const queue: WalkNode[] = [from];
48	  while (queue.length > 0) {
49	    const node = queue.shift()!;
50	    for (const next of WALK_GRAPH[node]) {
51	      if (seen.has(next)) continue;
52	      seen.add(next);
53	      previous.set(next, node);
54	      if (next === to) {
55	        const path: WalkNode[] = [to];
56	        let cursor: WalkNode = to;
57	        while (cursor !== from) {
58	          cursor = previous.get(cursor)!;
59	          path.unshift(cursor);
60	        }
61	        return path;
62	      }
63	      queue.push(next);
64	    }
65	  }
66	  return [from];
67	}
68	
69	function samePoint(a: Point, b: Point): boolean {
70	  return Math.abs(a.x - b.x) < 0.001 && Math.abs(a.y - b.y) < 0.001;
71	}
72	
73	/**
74	 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
75	 * hallway instead of cutting diagonally through a room.
76	 *
77	 * Each leg is at most three straight moves — out to the hallway, along it,
78	 * then in to the station — so every segment of the returned path is
79	 * axis-aligned. Zero-length moves are dropped, so a station already on the
80	 * hallway costs one segment, not three. The path includes `start` as its
81	 * first point.
82	 */
83	export function corridorPoints(
84	  start: Point,
85	  nodes: readonly WalkNode[],
86	  waypoints: Record<WalkNode, Point>,
87	  spineY: number,
88	): Point[] {
89	  const points: Point[] = [{ x: start.x, y: start.y }];
90	  const push = (point: Point) => {
91	    const last = points[points.length - 1]!;
92	    if (!samePoint(last, point)) points.push(point);
93	  };
94	  for (const node of nodes) {
95	    const target = waypoints[node];
96	    if (!target) continue;
97	    const from = points[points.length - 1]!;
98	    if (samePoint(from, target)) continue;
99	    // Step out to the hallway before moving sideways, and only step off it
100	    // once we're above/below the station we're headed for.
101	    if (from.x !== target.x) {
102	      push({ x: from.x, y: spineY });
103	      push({ x: target.x, y: spineY });
104	    }
105	    push({ x: target.x, y: target.y });
106	  }
107	  return points;
108	}
109	
110	/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
111	export function hopDurationMs(from: Point, to: Point): number {
112	  const distance = Math.hypot(to.x - from.x, to.y - from.y);
113	  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
114	}
115	
116	/** Ease in and out of each hop, so a walk starts and lands instead of snapping. */
117	function ease(t: number): number {
118	  return t * t * (3 - 2 * t);
119	}
120	
121	interface Hop {
122	  from: Point;
123	  to: Point;
124	  ms: number;
125	  /** Set when this hop lands exactly on a station, so `node` stays honest. */
126	  node?: WalkNode;
127	}
128	
129	export class StaffWalker {
130	  x: number;
131	  y: number;
132	  facing: 1 | -1 = 1;
133	  walking = false;
134	  /** True while the player has this worker's token in hand. */
135	  dragging = false;
136	  /** The station the walker is at — or has most recently walked through. */
137	  node: WalkNode;
138	
139	  private hops: Hop[] = [];
140	  private hopIndex = 0;
141	  private elapsedMs = 0;
142	  /** Where the current walk is headed, so a re-issued target doesn't restart it. */
143	  private targetNode: WalkNode;
144	
145	  constructor(node: WalkNode, slot: Point) {
146	    this.node = node;
147	    this.targetNode = node;
148	    this.x = slot.x;
149	    this.y = slot.y;
