61	        return path;
62	      }
63	      queue.push(next);
64	    }
65	  }
66	  return [from];
67	}
68	
69	function samePoint(a: Point, b: Point): boolean {
70	  return Math.abs(a.x - b.x) < 0.001 && Math.abs(a.y - b.y) < 0.001;
71	}
72	
73	/**
74	 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
75	 * hallway instead of cutting diagonally through a room.
76	 *
77	 * Each leg is at most three straight moves — out to the hallway, along it,
78	 * then in to the station — so every segment of the returned path is
79	 * axis-aligned. Zero-length moves are dropped, so a station already on the
80	 * hallway costs one segment, not three. The path includes `start` as its
81	 * first point.
82	 */
83	export function corridorPoints(
84	  start: Point,
85	  nodes: readonly WalkNode[],
86	  waypoints: Record<WalkNode, Point>,
87	  spineY: number,
88	): Point[] {
89	  const points: Point[] = [{ x: start.x, y: start.y }];
90	  const push = (point: Point) => {
91	    const last = points[points.length - 1]!;
92	    if (!samePoint(last, point)) points.push(point);
93	  };
94	  for (const node of nodes) {
95	    const target = waypoints[node];
96	    if (!target) continue;
97	    const from = points[points.length - 1]!;
98	    if (samePoint(from, target)) continue;
99	    // Step out to the hallway before moving sideways, and only step off it
100	    // once we're above/below the station we're headed for.
101	    if (from.x !== target.x) {
102	      push({ x: from.x, y: spineY });
103	      push({ x: target.x, y: spineY });
104	    }
105	    push({ x: target.x, y: target.y });
106	  }
107	  return points;
108	}
109	
110	/** Duration of a single straight hop between two points, at WALK_SPEED_PX_PER_SEC. */
111	export function hopDurationMs(from: Point, to: Point): number {
112	  const distance = Math.hypot(to.x - from.x, to.y - from.y);
113	  return (distance / WALK_SPEED_PX_PER_SEC) * 1000;
114	}
115	
116	/** Ease in and out of each hop, so a walk starts and lands instead of snapping. */
117	function ease(t: number): number {
118	  return t * t * (3 - 2 * t);
119	}
120	
121	interface Hop {
122	  from: Point;
123	  to: Point;
124	  ms: number;
125	  /** Set when this hop lands exactly on a station, so `node` stays honest. */
126	  node?: WalkNode;
127	}
128	
129	export class StaffWalker {
130	  x: number;
131	  y: number;
132	  facing: 1 | -1 = 1;
133	  walking = false;
134	  /** True while the player has this worker's token in hand. */
135	  dragging = false;
136	  /** The station the walker is at — or has most recently walked through. */
137	  node: WalkNode;
138	
139	  private hops: Hop[] = [];
140	  private hopIndex = 0;
141	  private elapsedMs = 0;
142	  /** Where the current walk is headed, so a re-issued target doesn't restart it. */
143	  private targetNode: WalkNode;
144	
145	  constructor(node: WalkNode, slot: Point) {
146	    this.node = node;
147	    this.targetNode = node;
148	    this.x = slot.x;
149	    this.y = slot.y;
150	  }
151	
152	  /** Teleport onto `slot`/`node` with no walk in progress (e.g. after a drag drop). */
153	  snap(slot: Point, node: WalkNode): void {
154	    this.x = slot.x;
155	    this.y = slot.y;
156	    this.node = node;
157	    this.targetNode = node;
158	    this.hops = [];
159	    this.hopIndex = 0;
160	    this.elapsedMs = 0;
161	    this.walking = false;
162	  }
163	
164	  /** Walk toward `target` from the current pixel, along the hallway at `spineY`. */
165	  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
166	    const slot = waypoints[target];
167	    if (!slot) return;
168	    // Re-issued every repaint while a walk is in flight; restarting the hop
169	    // each time would leave the worker jittering in place forever.
170	    if (this.walking && this.targetNode === target) return;
171	    if (!this.walking && this.node === target && samePoint(this, slot)) {
172	      this.targetNode = target;
173	      return;
174	    }
175	
176	    const nodes = bfsPath(this.node, target);
177	    const points = corridorPoints({ x: this.x, y: this.y }, nodes, waypoints, spineY);
178	    this.targetNode = target;
179	    this.hops = [];
180	    this.hopIndex = 0;
181	    this.elapsedMs = 0;
182	
183	    // Which points are stations, in order, so passing the pass updates `node`
184	    // rather than the whole trip counting as "still in the kitchen".
185	    const stationAt = new Map<number, WalkNode>();
186	    let cursor = 0;
187	    for (const node of nodes) {
188	      const waypoint = waypoints[node];
189	      if (!waypoint) continue;
190	      for (let i = cursor; i < points.length; i++) {
191	        if (samePoint(points[i]!, waypoint)) {
192	          stationAt.set(i, node);
193	          cursor = i + 1;
194	          break;
195	        }
196	      }
197	    }
198	
199	    for (let i = 1; i < points.length; i++) {
200	      const from = points[i - 1]!;
201	      const to = points[i]!;
202	      this.hops.push({ from, to, ms: hopDurationMs(from, to), node: stationAt.get(i) });
203	    }
204	    if (this.hops.length === 0) {
205	      this.x = slot.x;
206	      this.y = slot.y;
207	      this.node = target;
208	      this.walking = false;
209	      return;
210	    }
211	    this.walking = true;
212	  }
213	
214	  /**
215	   * Advance the walk by `dtMs` at simulation `speed` (0 pauses). Returns
216	   * whether the pixel position changed.
217	   */
218	  step(dtMs: number, speed: number): boolean {
219	    if (!this.walking || this.dragging) return false;
220	    if (!(dtMs > 0) || !(speed > 0)) return false;
221	
222	    const startX = this.x;
223	    const startY = this.y;
224	    let remaining = dtMs * speed;
225	
226	    while (remaining > 0 && this.hopIndex < this.hops.length) {
227	      const hop = this.hops[this.hopIndex]!;
228	      const left = hop.ms - this.elapsedMs;
229	      if (remaining < left) {
230	        this.elapsedMs += remaining;
231	        remaining = 0;
232	        const t = ease(hop.ms > 0 ? this.elapsedMs / hop.ms : 1);
233	        this.x = hop.from.x + (hop.to.x - hop.from.x) * t;
234	        this.y = hop.from.y + (hop.to.y - hop.from.y) * t;
235	        break;
236	      }
237	      // This hop is done — land exactly on it and carry the overflow into the
238	      // next one, so a long frame doesn't lose distance or overshoot a corner.
239	      remaining -= Math.max(0, left);
240	      this.x = hop.to.x;
241	      this.y = hop.to.y;
242	      if (hop.node) this.node = hop.node;
243	      this.hopIndex += 1;
244	      this.elapsedMs = 0;
245	    }
246	
247	    if (this.hopIndex >= this.hops.length) {
248	      this.node = this.targetNode;
249	      this.walking = false;
250	      this.hops = [];
251	      this.hopIndex = 0;
252	      this.elapsedMs = 0;
253	    }
254	
255	    if (this.x !== startX) this.facing = this.x > startX ? 1 : -1;
256	    return this.x !== startX || this.y !== startY;
257	  }
258	}
259

