  expect(walker.walking).toBe(false);
  return ms;
}

describe("WALK_GRAPH", () => {
  it("wires the four stations as one hallway", () => {
    expect(WALK_GRAPH).toEqual({
      kitchen: ["pass"],
      pass: ["kitchen", "floor"],
      floor: ["pass", "queue"],
      queue: ["floor"],
    });
  });

  it("has only symmetric edges", () => {
    for (const node of NODES) {
      for (const neighbour of WALK_GRAPH[node]) {
        expect(WALK_GRAPH[neighbour]).toContain(node);
      }
    }
  });
});

describe("bfsPath", () => {
  it("routes kitchen to queue through both through-stations", () => {
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
  });

  it("routes shorter trips too", () => {
    expect(bfsPath("kitchen", "pass")).toEqual(["kitchen", "pass"]);
    expect(bfsPath("kitchen", "floor")).toEqual(["kitchen", "pass", "floor"]);
    expect(bfsPath("floor", "queue")).toEqual(["floor", "queue"]);
    expect(bfsPath("pass", "queue")).toEqual(["pass", "floor", "queue"]);
  });

  it("is a single node when you are already there", () => {
    for (const node of NODES) expect(bfsPath(node, node)).toEqual([node]);
  });

  it("finds the shortest route between every pair", () => {
    for (const from of NODES) {
      for (const to of NODES) {
        const path = bfsPath(from, to);
        expect(path[0]).toBe(from);
        expect(path[path.length - 1]).toBe(to);
        // Consecutive entries are always adjacent, and nothing repeats.
        expect(new Set(path).size).toBe(path.length);
        for (let i = 1; i < path.length; i++) {
          expect(WALK_GRAPH[path[i - 1]!]).toContain(path[i]!);
        }
        expect(path.length).toBe(Math.abs(NODES.indexOf(from) - NODES.indexOf(to)) + 1);
      }
    }
  });
});

describe("corridorPoints", () => {
  it("rides the hallway instead of cutting across rooms", () => {
    const path = corridorPoints(waypoints.kitchen, bfsPath("kitchen", "queue"), waypoints, spineY);
    expect(path[0]).toEqual({ x: waypoints.kitchen.x, y: waypoints.kitchen.y });
    expect(path[path.length - 1]).toEqual({ x: waypoints.queue.x, y: waypoints.queue.y });

    for (let i = 1; i < path.length; i++) {
      const from = path[i - 1]!;
      const to = path[i]!;
      const axisAligned = from.x === to.x || from.y === to.y;
      expect(axisAligned, `segment ${i} is diagonal`).toBe(true);
    }

    // Every sideways move happens on the hallway line, never across a room.
    for (let i = 1; i < path.length; i++) {
      const from = path[i - 1]!;
      const to = path[i]!;
      if (from.x !== to.x) {
        expect(from.y).toBeCloseTo(spineY, 6);
        expect(to.y).toBeCloseTo(spineY, 6);
      }
    }
  });

  it("passes through each station's waypoint in order", () => {
    const nodes = bfsPath("kitchen", "queue");
    const path = corridorPoints(waypoints.kitchen, nodes, waypoints, spineY);
    let cursor = 0;
    for (const node of nodes) {
      const at = path.findIndex(
        (point, i) =>
          i >= cursor &&
          Math.abs(point.x - waypoints[node].x) < 0.001 &&
          Math.abs(point.y - waypoints[node].y) < 0.001,
      );
      expect(at, `${node} missing from the path`).toBeGreaterThanOrEqual(cursor);
      cursor = at + 1;
    }
  });

  it("drops zero-length moves", () => {
    const path = corridorPoints(waypoints.pass, ["pass"], waypoints, spineY);
    expect(path).toEqual([{ x: waypoints.pass.x, y: waypoints.pass.y }]);
    // Two stations that already sit on the hallway cost one straight segment.
    const flat = corridorPoints({ x: 0, y: spineY }, ["floor"], { ...waypoints, floor: { x: 100, y: spineY } }, spineY);
    expect(flat).toEqual([
      { x: 0, y: spineY },
      { x: 100, y: spineY },
    ]);
  });

  it("starts from the current pixel, not from the first station", () => {
    const start: Point = { x: waypoints.kitchen.x + 40, y: waypoints.kitchen.y + 12 };
    const path = corridorPoints(start, bfsPath("kitchen", "pass"), waypoints, spineY);
    expect(path[0]).toEqual(start);
  });
});

describe("hopDurationMs", () => {
  it("walks at 200px/s", () => {
    expect(WALK_SPEED_PX_PER_SEC).toBe(200);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 200, y: 0 })).toBe(1000);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 0, y: 100 })).toBe(500);
    expect(hopDurationMs({ x: 30, y: 40 }, { x: 0, y: 0 })).toBe(250);
    expect(hopDurationMs({ x: 7, y: 9 }, { x: 7, y: 9 })).toBe(0);
  });
});

describe("StaffWalker", () => {
  it("starts parked on its slot", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
    expect(walker.node).toBe("kitchen");
    expect(walker.walking).toBe(false);
    expect(walker.dragging).toBe(false);
    expect(walker.step(16, 1)).toBe(false);
  });

  it("walks the hallway to a far station and lands on its waypoint", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.walking).toBe(true);

    const seen: Point[] = [];
    while (walker.walking) {
      walker.step(16, 1);
      seen.push({ x: walker.x, y: walker.y });
    }

    expect(walker.node).toBe("queue");
    expect(walker.x).toBeCloseTo(waypoints.queue.x, 6);
    expect(walker.y).toBeCloseTo(waypoints.queue.y, 6);
    // It went the long way round: it visited the hallway line.
    expect(seen.some((point) => Math.abs(point.y - spineY) < 0.001)).toBe(true);
    // And it took about as long as the corridor is long.
    const path = corridorPoints(waypoints.kitchen, bfsPath("kitchen", "queue"), waypoints, spineY);
    let expected = 0;
    for (let i = 1; i < path.length; i++) expected += hopDurationMs(path[i - 1]!, path[i]!);
    expect(seen.length * 16).toBeGreaterThanOrEqual(expected);
    expect(seen.length * 16).toBeLessThan(expected + 100);
  });

  it("updates node as it passes through a station", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    const passedThrough = new Set<WalkNode>();
    while (walker.walking) {
      walker.step(16, 1);
      passedThrough.add(walker.node);
    }
    expect(passedThrough.has("pass")).toBe(true);
    expect(passedThrough.has("floor")).toBe(true);
  });

  it("eases each hop instead of moving at a constant rate", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("pass", waypoints, spineY);
    let previous = { x: walker.x, y: walker.y };
    const deltas: number[] = [];
    while (walker.walking) {
      walker.step(16, 1);
      deltas.push(Math.hypot(walker.x - previous.x, walker.y - previous.y));
      previous = { x: walker.x, y: walker.y };
    }
    // The first frame of the walk is slower than the middle of it.
    const middle = deltas[Math.floor(deltas.length / 2)]!;
    expect(deltas[0]!).toBeLessThan(middle);
    expect(Math.max(...deltas)).toBeGreaterThan(deltas[0]! * 2);
  });

  it("faces the way it is moving", () => {
    const left = new StaffWalker("queue", waypoints.queue);
    left.setTarget("kitchen", waypoints, spineY);
    runToRest(left);
    expect(left.facing).toBe(-1);

    const right = new StaffWalker("kitchen", waypoints.kitchen);
    right.setTarget("queue", waypoints, spineY);
    runToRest(right);
    expect(right.facing).toBe(1);
  });

  it("holds still at speed 0 and moves twice as far at speed 2", () => {
    const paused = new StaffWalker("kitchen", waypoints.kitchen);
    paused.setTarget("queue", waypoints, spineY);
    const before = { x: paused.x, y: paused.y };
    expect(paused.step(16, 0)).toBe(false);
    expect(paused.x).toBe(before.x);
    expect(paused.y).toBe(before.y);
    expect(paused.walking).toBe(true);

    const slow = new StaffWalker("kitchen", waypoints.kitchen);
    slow.setTarget("queue", waypoints, spineY);
    const fast = new StaffWalker("kitchen", waypoints.kitchen);
    fast.setTarget("queue", waypoints, spineY);
    slow.step(200, 1);
    fast.step(100, 2);
    expect(fast.x).toBeCloseTo(slow.x, 6);
    expect(fast.y).toBeCloseTo(slow.y, 6);
  });

  it("does not restart the walk when the same target is re-issued", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(300, 1);
    const midway = { x: walker.x, y: walker.y };
    walker.setTarget("queue", waypoints, spineY);
    expect(walker.x).toBe(midway.x);
    expect(walker.y).toBe(midway.y);
    walker.step(16, 1);
    expect(Math.hypot(walker.x - midway.x, walker.y - midway.y)).toBeLessThan(16 * 0.2 + 1);
  });

  it("stays put when told to walk to where it already is", () => {
    const walker = new StaffWalker("pass", waypoints.pass);
    walker.setTarget("pass", waypoints, spineY);
    expect(walker.walking).toBe(false);
    expect(walker.x).toBe(waypoints.pass.x);
    expect(walker.y).toBe(waypoints.pass.y);
  });

  it("re-routes to a new target mid-walk", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(400, 1);
    walker.setTarget("kitchen", waypoints, spineY);
    runToRest(walker);
    expect(walker.node).toBe("kitchen");
    expect(walker.x).toBeCloseTo(waypoints.kitchen.x, 6);
    expect(walker.y).toBeCloseTo(waypoints.kitchen.y, 6);
  });

  it("freezes while dragged and resumes after", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(200, 1);
    walker.dragging = true;
    const held = { x: walker.x, y: walker.y };
    expect(walker.step(500, 1)).toBe(false);
    expect(walker.x).toBe(held.x);
    walker.dragging = false;
    expect(walker.step(16, 1)).toBe(true);
  });

  it("snaps onto a dropped slot with no walk left over", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(200, 1);
    walker.snap(waypoints.floor, "floor");
    expect(walker.node).toBe("floor");
    expect(walker.walking).toBe(false);
    expect(walker.x).toBe(waypoints.floor.x);
    expect(walker.y).toBe(waypoints.floor.y);
    expect(walker.step(16, 1)).toBe(false);
    // And the abandoned trip does not come back on the next tick.
    walker.setTarget("floor", waypoints, spineY);
    expect(walker.walking).toBe(false);
  });

  it("lands exactly on target even with one absurdly long frame", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    walker.setTarget("queue", waypoints, spineY);
    walker.step(60_000, 1);
    expect(walker.walking).toBe(false);
    expect(walker.node).toBe("queue");
    expect(walker.x).toBe(waypoints.queue.x);
    expect(walker.y).toBe(waypoints.queue.y);
  });

  it("walks between every pair of stations without getting stuck", () => {
    for (const from of NODES) {
      for (const to of NODES) {
        const walker = new StaffWalker(from, waypoints[from]);
        walker.setTarget(to, waypoints, spineY);
        runToRest(walker);
        expect(walker.node, `${from} -> ${to}`).toBe(to);
        expect(walker.x).toBeCloseTo(waypoints[to].x, 6);
        expect(walker.y).toBeCloseTo(waypoints[to].y, 6);
      }
    }
  });
});

