import { describe, expect, it } from "bun:test";
import { RepaintGate } from "./restaurant-arena-repaint-gate.js";

describe("RepaintGate", () => {
  it("starts idle and paints straight through", () => {
    const gate = new RepaintGate();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
    expect(gate.requestPaint()).toBe(true);
    // Nothing was held, so nothing is owed if a drag opens and closes.
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  it("holds paints while a drag is open", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.isDragging).toBe(true);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
    expect(gate.isDragging).toBe(false);
  });

  it("owes exactly one repaint however many were held", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    for (let i = 0; i < 25; i++) expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
    // The debt is settled by that one repaint, not re-owed.
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  it("does not carry a debt from one drag into the next", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    expect(gate.endDrag()).toBe(true);
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
  });

  it("drops the drag and the debt on resize", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    // The stray dragend that arrives after the canvas was rebuilt owes nothing.
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  it("takes paints again immediately after a resize mid-drag", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.resize();
    expect(gate.requestPaint()).toBe(true);
    expect(gate.endDrag()).toBe(false);
  });

  it("survives a resize with no drag open", () => {
    const gate = new RepaintGate();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });
});

