it("faces the way it is moving", () => {
  // Stations strung left to right along the hallway, so the last sideways
  // move of a trip is unambiguous (the real host stand is not necessarily
  // right of the dining room's centre).
  const flat: Record<WalkNode, Point> = {
    kitchen: { x: 0, y: 0 },
    pass: { x: 60, y: 0 },
    floor: { x: 140, y: 0 },
    queue: { x: 220, y: 20 },
  };
  const right = new StaffWalker("kitchen", flat.kitchen);
  right.setTarget("queue", flat, 0);
  runToRest(right);
  expect(right.facing).toBe(1);

  const left = new StaffWalker("queue", flat.queue);
  left.setTarget("kitchen", flat, 0);
  runToRest(left);
  expect(left.facing).toBe(-1);

  // Facing is sticky through a purely vertical hop: stepping off the hallway
  // onto the host stand does not spin the figure round.
  const stepIn = new StaffWalker("floor", flat.floor);
  stepIn.setTarget("queue", flat, 0);
  runToRest(stepIn);
  expect(stepIn.facing).toBe(1);
});

